                }
            }
            return null;
    }

    private static function reduceColumnConstraint(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];

            $type           = '';
            $expression     = null;
            $value          = null;
            $fk             = null;
            $conflictAction = null;
            $autoincrement  = false;
            $asc            = null;

            $flat = [];
            $collect = static function ($items) use (&$collect, &$flat): void {
                foreach ($items as $item) {
                    if (\is_array($item)) {
                        $collect($item);
                    } else {
                        $flat[] = $item;
                    }
                }
            };
            $collect($children);

            foreach ($flat as $item) {
                if ($item instanceof \Phplrt\Contracts\Lexer\TokenInterface) {
                    $u = \strtoupper($item->value);
                    if ($u === 'PRIMARY') {
                        $type = 'PRIMARY_KEY';
                    } elseif ($u === 'UNIQUE') {
                        $type = 'UNIQUE';
                    } elseif ($u === 'CHECK') {
                        $type = 'CHECK';
                    } elseif ($u === 'DEFAULT') {
                        $type = 'DEFAULT';
                    } elseif ($u === 'COLLATE') {
                        $type = 'COLLATE';
                    } elseif ($u === 'NOT') {
                        $type = 'NOT_NULL';
                    } elseif ($u === 'AUTOINCREMENT') {
                        $autoincrement = true;
                    } elseif ($type === 'COLLATE' && $value === null) {
                        $value = $item->value;
                    }
                    continue;
                }
                if ($item instanceof \Inilim\SqliteParser\Ast\Expression) {
                    if ($type === 'CHECK' || $type === 'DEFAULT') {
                        $expression = $item;
                    }
                    continue;
                }
                if ($item instanceof \Inilim\SqliteParser\Ast\Statement\ForeignKeyClause) {
                    $type = 'REFERENCES';
                    $fk = $item;
                    continue;
                }
                if (\is_string($item)) {
                    if ($item === 'ASC') {
                        $asc = true;
                    } elseif ($item === 'DESC') {
                        $asc = false;
                    } elseif ($item !== '') {
                        $conflictAction = $item;
                    }
                    continue;
                }
            }

            return new \Inilim\SqliteParser\Ast\Statement\ColumnConstraint(
                type: $type,
                expression: $expression,
                value: $value,
                foreignKey: $fk,
                conflictAction: $conflictAction,
                autoincrement: $autoincrement,
                asc: $asc,
            );
    }

    private static function reduceTableOptions(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];

            $withoutRowid = false;
            $strict = false;

            $flat = [];
            $collect = static function ($items) use (&$collect, &$flat): void {
                foreach ($items as $item) {
                    if (\is_array($item)) {
                        $collect($item);
                    } else {
                        $flat[] = $item;
                    }
                }
            };
            $collect($children);

            foreach ($flat as $item) {
                if ($item instanceof \Phplrt\Contracts\Lexer\TokenInterface) {
                    $u = \strtoupper($item->value);
                    if ($u === 'WITHOUT') {
                        $withoutRowid = true;
                    } elseif ($u === 'STRICT') {
                        $strict = true;
