            return new \Inilim\SqliteParser\Ast\Statement\TableOptions($withoutRowid, $strict);
    }

    private static function reduceCreateIndexStatement(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];

            $name        = '';
            $table       = '';
            $columns     = [];
            $unique      = false;
            $ifNotExists = false;
            $where       = null;

            $flat = [];
            $collect = static function ($items) use (&$collect, &$flat): void {
                foreach ($items as $item) {
                    if (\is_array($item)) {
                        $collect($item);
                    } else {
                        $flat[] = $item;
                    }
                }
            };
            $collect($children);

            // Нормализует один элемент списка индексируемых выражений:
            // простые ColumnReference без таблицы -> строковое имя колонки,
            // всё остальное -> как есть (Expression).
            $normalize = static function ($col) {
                if ($col instanceof \Inilim\SqliteParser\Ast\Expression\ColumnReference
                    && $col->table === null
                ) {
                    return $col->name;
                }
                return $col;
            };

            $nameSet = false;
            foreach ($flat as $item) {
                if ($item instanceof \Phplrt\Contracts\Lexer\TokenInterface) {
                    $u = \strtoupper($item->value);
                    if ($u === 'UNIQUE') {
                        $unique = true;
                    }
                    continue;
                }
                if ($item === 'IF_NOT_EXISTS') {
                    $ifNotExists = true;
                    continue;
                }
                if ($item instanceof \Inilim\SqliteParser\Ast\Statement\IdentListWrapper) {
                    $columns = $item->items;
                    continue;
                }
                if ($item instanceof \Inilim\SqliteParser\Ast\Expression\ExpressionList) {
                    $columns = [];
                    foreach ($item->items as $col) {
                        $columns[] = $normalize($col);
                    }
                    continue;
                }
                if ($item instanceof \Inilim\SqliteParser\Ast\Expression) {
                    $where = $item;
                    continue;
                }
                if (\is_string($item)) {
                    if (!$nameSet) {
                        $name = $item;
                        $nameSet = true;
                    } else {
                        $table = $item;
                    }
                    continue;
                }
            }

            return new \Inilim\SqliteParser\Ast\Statement\CreateIndexStatement(
                name: $name,
                table: $table,
                columns: $columns,
                unique: $unique,
                ifNotExists: $ifNotExists,
                where: $where,
            );
    }

    private static function reduceCreateViewStatement(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];

            $name        = '';
            $select      = null;
            $ifNotExists = false;
            $temporary   = false;
            $columns     = null;

            $flat = [];
            $collect = static function ($items) use (&$collect, &$flat): void {
                foreach ($items as $item) {
                    if (\is_array($item)) {
                        $collect($item);
                    } else {
                        $flat[] = $item;
                    }
                }
            };
            $collect($children);

            $nameSet = false;
            foreach ($flat as $item) {
                if ($item === 'TEMP' || $item === 'TEMPORARY') {
                    $temporary = true;
                    continue;
                }
                if ($item === 'IF_NOT_EXISTS') {
                    $ifNotExists = true;
                    continue;
                }
                if ($item instanceof \Inilim\SqliteParser\Ast\Statement) {
                    $select = $item;
                    continue;
                }
                if ($item instanceof \Inilim\SqliteParser\Ast\Statement\IdentListWrapper) {
                    $columns = $item->items;
                    continue;
                }
                if (\is_string($item) && !$nameSet) {
                    $name = $item;
                    $nameSet = true;
                    continue;
                }
            }

            if ($select === null) {
                throw new \LogicException('CREATE VIEW without SELECT');
            }

            return new \Inilim\SqliteParser\Ast\Statement\CreateViewStatement(
                name: $name,
                select: $select,
                ifNotExists: $ifNotExists,
                temporary: $temporary,
                columns: $columns,
            );
    }

    private static function reduceCreateTriggerStatement(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        $children = \is_array($children) ? $children : [$children];

            $name        = '';
            $event       = '';
            $table       = '';
            $timing      = 'BEFORE';
            $updateOf    = [];
            $forEachRow  = false;
            $when        = null;
            $statements  = [];
            $ifNotExists = false;
            $temporary   = false;

            $flat = [];
            $collect = static function ($items) use (&$collect, &$flat): void {
                foreach ($items as $item) {
                    if (\is_array($item)) {
                        $collect($item);
                    } else {
                        $flat[] = $item;
                    }
                }
            };
            $collect($children);

            $nameSet = false;
            $tableSet = false;
            foreach ($flat as $item) {
                if ($item === 'TEMP' || $item === 'TEMPORARY') {
                    $temporary = true;
                    continue;
                }
                if ($item === 'IF_NOT_EXISTS') {
                    $ifNotExists = true;
                    continue;
                }
                if ($item === 'BEFORE' || $item === 'AFTER' || $item === 'INSTEAD') {
                    $timing = $item;
                    continue;
                }
                if ($item === 'FOR_EACH_ROW') {
                    $forEachRow = true;
                    continue;
                }
                if ($item instanceof \Inilim\SqliteParser\Ast\Statement\TriggerEventInfo) {
                    $event = $item->event;
                    $updateOf = $item->updateOf;
